mapper.select:
SELECT a.`uuid`, a.`name`, a.`handler`, a.`begin_time`, a.`end_time`, a.`cron`, a.`is_active`, a.`need_audit`, a.`source_server_id`, d.prop_name, d.prop_value, d.id as prop_id FROM `schedule_job` a LEFT JOIN schedule_job_prop d ON a.uuid = d.job_uuid WHERE `handler` = #{handler}
AND (a.source_server_id IS NULL OR a.source_server_id IN
#{sourceServerId}
)

SELECT
count(1)
FROM schedule_job a
WHERE
1=1

    AND a.name like CONCAT('%',#{keyword}, '%')


    AND a.handler = #{handler}


    AND a.handler IN

        #{handlerClassName}



    AND a.is_active = #{isActive}


    AND a.need_audit = #{needAudit}



    AND (a.source_server_id IS NULL OR a.source_server_id IN

        #{sourceServerId}

    )

SELECT a.`uuid`, a.name, a.handler, a.`begin_time`, a.`end_time`, a.cron, a.is_active, a.need_audit, a.source_server_id, sjs.job_name, sjs.job_group, sjs.last_fire_time, sjs.last_finish_time, sjs.next_fire_time, sjs.exec_count FROM schedule_job a LEFT JOIN schedule_job_status sjs ON a.uuid = sjs.job_name WHERE 1=1
AND a.name like CONCAT('%',#{keyword}, '%')
AND a.handler = #{handler}
AND a.handler IN
#{handlerClassName}
AND a.is_active = #{isActive}
AND a.need_audit = #{needAudit}
AND (a.source_server_id IS NULL OR a.source_server_id IN
#{sourceServerId}
)
ORDER BY a.`fcd` DESC limit #{startNum}, #{pageSize}

select count(1)
from schedule_job_audit_detail
where hash = #{value}

SELECT DATE_FORMAT(a.`start_time`, '%Y-%m-%d %H:%i:%s')
FROM `schedule_job_audit` a
WHERE a.job_uuid = #{jobUuid}
  AND a.`status` = #{status}
ORDER BY a.end_time DESC
LIMIT 1

select job_uuid as jobUuid,
data_name as name,
data_value as value
from schedule_job_data
where job_uuid = #{jobUuid}

    and data_name = #{name}

mapper.update:
UPDATE schedule_job_status
SET next_fire_time = #{nextFireTime},
    `lcd`          = NOW()
WHERE job_name = #{jobName}
  and job_group = #{jobGroup}

UPDATE schedule_job_audit
SET end_time     = now(3),
    status       = #{status},
    content_hash = #{contentHash}
WHERE id = #{id}

UPDATE `schedule_job_lock`
SET `server_id` = #{serverId},
    `lock`      = #{lock}
WHERE job_name = #{jobName}
  AND job_group = #{jobGroup}
